#include <iostream>

struct Matrix2x2 {
    int data[2][2];
};

// Unary operator- for Matrix2x2
Matrix2x2 operator-(const Matrix2x2& m) {
    Matrix2x2 res{};
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            res.data[i][j] = -m.data[i][j];
        }
    }
    return res;
}

// Binary operator+ for Matrix2x2
Matrix2x2 operator+(const Matrix2x2& a, const Matrix2x2& b) {
    Matrix2x2 res{};
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            res.data[i][j] = a.data[i][j] + b.data[i][j];
        }
    }
    return res;
}

int main() {
    Matrix2x2 m1{{{1, -2}, {3, -4}}};
    Matrix2x2 m2{{{5, 6}, {-7, 8}}};

    // Style 1: Explicit functional call
    Matrix2x2 neg1 = operator-(m1);
    // Style 2: Standard operator syntax
    Matrix2x2 sum = m1 + m2;

    std::cout << "Negated m1: [" << neg1.data[0][0] << ", " << neg1.data[0][1] << "; "
              << neg1.data[1][0] << ", " << neg1.data[1][1] << "]\n";
    std::cout << "Sum m1+m2: [" << sum.data[0][0] << ", " << sum.data[0][1] << "; "
              << sum.data[1][0] << ", " << sum.data[1][1] << "]\n";
    return 0;
}

#include <iostream>
#include <numeric> // std::gcd in C++17
#include <cstdlib>

struct PS {
    int a{0};
    int b{1};
};

int uscln(int x, int y) {
    x = std::abs(x);
    y = std::abs(y);
    if (x == 0 || y == 0) return (x == 0 ? y : x);
    while (x != y) {
        if (x > y) x -= y;
        else y -= x;
    }
    return x;
}

PS rutgon(PS p) {
    if (p.a == 0) return PS{0, 1};
    int g = uscln(p.a, p.b);
    p.a /= g;
    p.b /= g;
    if (p.b < 0) {
        p.a = -p.a;
        p.b = -p.b;
    }
    return p;
}

PS operator+(PS p1, PS p2) {
    PS q;
    q.a = p1.a * p2.b + p2.a * p1.b;
    q.b = p1.b * p2.b;
    return rutgon(q);
}

PS operator-(PS p1, PS p2) {
    PS q;
    q.a = p1.a * p2.b - p2.a * p1.b;
    q.b = p1.b * p2.b;
    return rutgon(q);
}

std::ostream& operator<<(std::ostream& os, const PS& p) {
    os << p.a << '/' << p.b;
    return os;
}

std::istream& operator>>(std::istream& is, PS& p) {
    is >> p.a >> p.b;
    return is;
}

int main() {
    PS p1{1, 2};
    PS p2{1, 3};
    PS sum = p1 + p2;
    PS diff = p1 - p2;

    std::cout << p1 << " + " << p2 << " = " << sum << "\n";
    std::cout << p1 << " - " << p2 << " = " << diff << "\n";
    return 0;
}
